import { sql } from 'drizzle-orm'
import {
  bigint,
  check,
  foreignKey,
  index,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
} from 'drizzle-orm/pg-core'
import { orgs } from './orgs'

/**
 * Typed relational projection for the `notification` bounded context (migration
 * feature D, brief 0060, Grupo C) — an operator-facing notification (birthday,
 * subscription expiry, stale order, …), generated by cron or by a domain event.
 *
 * Keyed by composite PK (org_id, id). FK `org_id → orgs.org_id`; `org_id` is the leading index column
 * (RLS performance). `unit_id` is NOT NULL (a notification targets a unit's
 * operators) and is the RLS unit predicate.
 *
 * Union mapping: the `type` (NotificationType) and `source` (cron | event)
 * discriminants are TEXT+CHECK columns; the opaque `payload` and the dispatch
 * snapshot (dispatchedChannel/dispatchedBody) ride in JSONB. `event_key` (the
 * idempotency key for cron generation) is a column for queryability.
 *
 * No PII: `payload` is opaque operational data referencing ids (customerId,
 * appointmentId), never personal data inline (ADR 0010).
 *
 * Invariants enforced HERE (proven by integration against real Postgres):
 *   - `type ∈ {birthday, subscription_expiring_tomorrow, subscription_expired,
 *     subscription_overdue_followup, order_stale, cash_register_open,
 *     new_customer, payment_failure}` — the enum, as a CHECK.
 *   - `source ∈ {cron, event}` — the enum, as a CHECK.
 *   - `unit_id` NOT NULL; FK `org_id → orgs.org_id`; `org_id` leading column.
 */
export const notifications = pgTable(
  'notifications',
  {
    // ── Identity + org/unit scope ───────────────────────────────────────────
    orgId: text('org_id').notNull(),
    id: text('id').notNull(),
    // A notification targets a unit's operators — the RLS unit predicate.
    unitId: text('unit_id').notNull(),

    // Monotonic projection version (the reducer's `_version`).
    lastEventVersion: bigint('last_event_version', { mode: 'number' }).notNull(),

    // ── Primary-metric invariants (enforced by the DB) ──────────────────────
    type: text('type').notNull(),
    source: text('source').notNull(),
    // Idempotency key for cron generation (queryable for dedup).
    eventKey: text('event_key').notNull(),

    // Reference ids (no PII) — nullable per notification type.
    customerId: text('customer_id'),
    appointmentId: text('appointment_id'),
    subscriptionId: text('subscription_id'),

    // Lifecycle timestamps (ISO text, mirror the domain `string | null`).
    readAt: timestamp('read_at', { withTimezone: true, mode: 'string' }),
    dispatchedAt: timestamp('dispatched_at', { withTimezone: true, mode: 'string' }),
    validUntil: timestamp('valid_until', { withTimezone: true, mode: 'string' }),
    snoozedUntil: timestamp('snoozed_until', { withTimezone: true, mode: 'string' }),

    // ── Composite / structural state (JSONB) ────────────────────────────────
    // Opaque operational payload (references ids, never PII inline).
    payload: jsonb('payload').notNull(),
    // Dispatch snapshot (AC-14): { dispatchedChannel, dispatchedBody }. Null
    // fields while not dispatched.
    dispatch: jsonb('dispatch'),

    createdAt: timestamp('created_at', { withTimezone: true, mode: 'string' }),
    updatedAt: timestamp('updated_at', { withTimezone: true, mode: 'string' }),
  },
  (table) => [
    // Composite (org_id, id) PRIMARY KEY — the natural key.
    primaryKey({ columns: [table.orgId, table.id], name: 'notifications_pkey' }),
    // The notification-type enum, refused at the DB.
    check(
      'notifications_type_check',
      sql`${table.type} IN (
        'birthday',
        'subscription_expiring_tomorrow',
        'subscription_expired',
        'subscription_overdue_followup',
        'order_stale',
        'cash_register_open',
        'new_customer',
        'payment_failure'
      )`,
    ),
    // The source enum, refused at the DB.
    check('notifications_source_check', sql`${table.source} IN ('cron', 'event')`),
    // A notification always targets a unit (non-empty unitId).
    check('notifications_unit_id_nonempty', sql`char_length(btrim(${table.unitId})) > 0`),
    // Every notification belongs to a real org.
    foreignKey({
      name: 'notifications_org_id_fk',
      columns: [table.orgId],
      foreignColumns: [orgs.orgId],
    }),
    // `org_id`-leading indexes: the RLS policy + per-unit notification reads +
    // the cron idempotency lookup by event_key.
    index('notifications_org_id_unit_id_idx').on(table.orgId, table.unitId),
    index('notifications_org_id_event_key_idx').on(table.orgId, table.eventKey),
  ],
)

export type StoredNotificationRow = typeof notifications.$inferSelect
export type NewNotificationRow = typeof notifications.$inferInsert
